#!/usr/bin/env node
/**
 * Writes `dist/effect-golem.d.ts`, the public types entry for the
 * package: a thin shim that
 *   1. /// references every ambient `.d.ts` in golem-types/, so that
 *      WIT host module names like `golem:agent/common@1.5.0` and
 *      `agent-guest` resolve in consumer projects, and
 *   2. re-exports the surface generated by tsc into dist/src/.
 */
import { fileURLToPath } from "node:url"
import { dirname, relative, resolve } from "node:path"
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs"
import ts from "typescript"

const here = dirname(fileURLToPath(import.meta.url))
const root = resolve(here, "..")
const typesDir = resolve(root, "golem-types")
const distDir = resolve(root, "dist")
const outFile = resolve(distDir, "effect-golem.d.ts")
const middlewareOutFile = resolve(distDir, "effect-golem-middleware.d.ts")
const aiOutFile = resolve(distDir, "effect-golem-ai.d.ts")
const sqliteOutFile = resolve(distDir, "effect-golem-sqlite.d.ts")
const postgresOutFile = resolve(distDir, "effect-golem-postgres.d.ts")
const mysqlOutFile = resolve(distDir, "effect-golem-mysql.d.ts")
const igniteOutFile = resolve(distDir, "effect-golem-ignite2.d.ts")

// Bundle the private source package so published consumers need neither source nor a sibling SDK.
const sharedEntry = fileURLToPath(import.meta.resolve("@golemcloud/http-contract"))
const sharedSource = readFileSync(sharedEntry, "utf8")
const sharedDir = resolve(distDir, "src/internal/http-contract")
mkdirSync(sharedDir, { recursive: true })
writeFileSync(
  resolve(sharedDir, "index.mjs"),
  ts.transpileModule(sharedSource, {
    compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext },
  }).outputText,
)
function localizeSharedImports(directory) {
  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    const path = resolve(directory, entry.name)
    if (entry.isDirectory()) {
      localizeSharedImports(path)
    } else if (path.endsWith(".js") || path.endsWith(".d.ts")) {
      const source = readFileSync(path, "utf8")
      if (!source.includes("@golemcloud/http-contract")) continue
      const target = `./${relative(directory, resolve(sharedDir, "index.mjs")).replaceAll("\\", "/")}`
      writeFileSync(path, source.replaceAll("@golemcloud/http-contract", target))
    }
  }
}
localizeSharedImports(resolve(distDir, "src"))

const refs = readdirSync(typesDir)
  .filter((f) => f.endsWith(".d.ts"))
  .sort()
  .map((f) => `/// <reference path="../golem-types/${f}" />`)
  .join("\n")

const sharedDeclaration = ts.transpileDeclaration(sharedSource, { fileName: sharedEntry })
if (sharedDeclaration.diagnostics?.length) {
  throw new Error(
    ts.formatDiagnosticsWithColorAndContext(sharedDeclaration.diagnostics, {
      getCanonicalFileName: (name) => name,
      getCurrentDirectory: () => root,
      getNewLine: () => "\n",
    }),
  )
}
writeFileSync(
  resolve(sharedDir, "index.d.mts"),
  refs.replaceAll("../golem-types/", "../../../../golem-types/") +
    "\n" +
    sharedDeclaration.outputText,
)

const body = `export * from "./src/index.js"\n`

writeFileSync(outFile, refs + "\n" + body, "utf-8")
console.log(`wrote ${outFile}`)

const middlewareBody = `export * from "./src/Middleware.js"\n`
writeFileSync(middlewareOutFile, refs + "\n" + middlewareBody, "utf-8")
console.log(`wrote ${middlewareOutFile}`)

const aiBody = `export * from "./src/Ai.js"\n`
writeFileSync(aiOutFile, refs + "\n" + aiBody, "utf-8")
console.log(`wrote ${aiOutFile}`)

const sqliteBody = `export * from "./src/Sqlite/SqliteClient.js"\n`
writeFileSync(sqliteOutFile, refs + "\n" + sqliteBody, "utf-8")
console.log(`wrote ${sqliteOutFile}`)

const postgresBody = `export * from "./src/Postgres/PgClient.js"\n`
writeFileSync(postgresOutFile, refs + "\n" + postgresBody, "utf-8")
console.log(`wrote ${postgresOutFile}`)

const mysqlBody = `export * from "./src/Mysql/MySqlClient.js"\n`
writeFileSync(mysqlOutFile, refs + "\n" + mysqlBody, "utf-8")
console.log(`wrote ${mysqlOutFile}`)

const igniteBody = `export * from "./src/Ignite/IgniteClient.js"\n`
writeFileSync(igniteOutFile, refs + "\n" + igniteBody, "utf-8")
console.log(`wrote ${igniteOutFile}`)

// Public subpaths must refer to the same stateful modules as the embedded SDK.
// Discover runtime exports with the compiler, without executing host-bound code in Node.
const configPath = resolve(root, "tsconfig.build.json")
const config = ts.readConfigFile(configPath, ts.sys.readFile)
if (config.error) throw new Error(ts.flattenDiagnosticMessageText(config.error.messageText, "\n"))
const parsed = ts.parseJsonConfigFileContent(config.config, ts.sys, root)
const program = ts.createProgram(parsed.fileNames, { ...parsed.options, noEmit: true })
const checker = program.getTypeChecker()
const index = program.getSourceFile(resolve(root, "src/index.ts"))
const witCodecFacade = resolve(distDir, "src/WitCodec.js")
const witCodecImplementation = resolve(distDir, "src/internal/WitCodec.js")

function relativeImport(fromFile, toFile) {
  const path = relative(dirname(fromFile), toFile).replaceAll("\\", "/")
  return path.startsWith(".") ? path : `./${path}`
}

function rewriteRelativeImports(source, fromFile, rewrite, outputFile = fromFile) {
  return source.replace(/(["'])(\.\.?\/[^"']+)\1/g, (match, quote, specifier) => {
    const target = resolve(dirname(fromFile), specifier)
    const replacement = rewrite(target)
    return replacement ? `${quote}${relativeImport(outputFile, replacement)}${quote}` : match
  })
}

const witCodecSource = readFileSync(witCodecFacade, "utf8")
writeFileSync(
  witCodecImplementation,
  rewriteRelativeImports(
    witCodecSource,
    witCodecFacade,
    (target) => target,
    witCodecImplementation,
  ),
)
function redirectWitCodecImports(directory) {
  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    const path = resolve(directory, entry.name)
    if (entry.isDirectory()) {
      redirectWitCodecImports(path)
    } else if (path.endsWith(".js") && path !== witCodecImplementation) {
      const source = readFileSync(path, "utf8")
      const rewritten = rewriteRelativeImports(source, path, (target) =>
        target === witCodecFacade ? witCodecImplementation : undefined,
      )
      if (rewritten !== source) writeFileSync(path, rewritten)
    }
  }
}
redirectWitCodecImports(resolve(distDir, "src"))

const facades = index.statements
  .filter(
    (node) =>
      ts.isExportDeclaration(node) && node.exportClause && ts.isNamespaceExport(node.exportClause),
  )
  .map((node) => [
    node.moduleSpecifier.text.slice(2, -3),
    resolve(distDir, "index.mjs"),
    node.exportClause.name.text,
  ])
facades.push(
  ["ToolReflection", resolve(distDir, "index.mjs"), "Reflection"],
  ["Sqlite/SqliteClient", resolve(distDir, "sqlite.mjs")],
  ["Postgres/PgClient", resolve(distDir, "postgres.mjs")],
  ["Mysql/MySqlClient", resolve(distDir, "mysql.mjs")],
  ["Ignite/IgniteClient", resolve(distDir, "ignite.mjs")],
)
for (const [modulePath, owner, namespace] of facades) {
  const source = program.getSourceFile(resolve(root, "src", `${modulePath}.ts`))
  const exports = checker
    .getExportsOfModule(checker.getSymbolAtLocation(source))
    .filter((symbol) => {
      if (symbol.declarations?.some(ts.isTypeOnlyImportOrExportDeclaration)) return false
      const target = symbol.flags & ts.SymbolFlags.Alias ? checker.getAliasedSymbol(symbol) : symbol
      return target.flags & ts.SymbolFlags.Value
    })
  const names = new Set(exports.map((symbol) => symbol.name))
  // Effect's JavaScript can export values omitted from its declarations.
  for (const node of source.statements) {
    if (
      ts.isExportDeclaration(node) &&
      !node.isTypeOnly &&
      !node.exportClause &&
      node.moduleSpecifier?.text.startsWith("effect/")
    ) {
      for (const name of Object.keys(await import(node.moduleSpecifier.text))) {
        if (name !== "default") names.add(name)
      }
    }
  }
  const output = resolve(distDir, "src", `${modulePath}.js`)
  const ownerImport = relativeImport(output, owner)
  const imports = namespace
    ? `import { ${namespace} as shared } from ${JSON.stringify(ownerImport)};`
    : `import * as shared from ${JSON.stringify(ownerImport)};`
  writeFileSync(
    output,
    [
      imports,
      ...[...names].map(
        (name, index) =>
          `const sharedExport${index} = /* @__PURE__ */ (() => shared.${name})(); export { sharedExport${index} as ${name} };`,
      ),
      "",
    ].join("\n"),
  )
}
writeFileSync(resolve(distDir, "src/index.js"), 'export * from "@golemcloud/effect-golem";\n')
